"use client";

import * as React from "react";
import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const Tabs = TabsPrimitive.Root;

/**
 * Firefly TabsList: a row of labels standing on a warm hairline. Nothing
 * fills behind the active tab; a short ink underline marks it instead.
 */
const TabsList = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.List.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    data-slot="tabs-list"
    className={cn(
      "inline-flex items-center gap-1 border-b border-border text-muted-foreground",
      className,
    )}
    {...props}
  />
));
TabsList.displayName = "TabsList";

/**
 * Firefly TabsTrigger: muted ink that darkens on hover. The active tab
 * turns near-black and an ink underline fades in under its label.
 */
const TabsTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TabsPrimitive.Tab.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Tab
    ref={ref}
    data-slot="tabs-trigger"
    className={cn(
      "relative inline-flex h-10 shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-t-md px-3",
      "text-sm font-medium text-muted-foreground",
      "transition-colors duration-fast ease-out hover:text-foreground",
      "after:absolute after:inset-x-3 after:-bottom-px after:h-0.5 after:rounded-full after:bg-(--ink)",
      "after:opacity-0 after:transition-opacity after:duration-fast after:ease-out",
      "data-[active]:text-foreground data-[active]:after:opacity-100",
      "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
      "data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
      "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
      className,
    )}
    {...props}
  />
));
TabsTrigger.displayName = "TabsTrigger";

/** Firefly TabsContent: the active panel, set a little below the tab row. */
const TabsContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<TabsPrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Panel
    ref={ref}
    data-slot="tabs-content"
    className={cn(
      "mt-4 rounded-md focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
      className,
    )}
    {...props}
  />
));
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };
